<x-hris.table id="ipcr-table" endpoint="/ipcr/data" :columns="[['key'=>'employee.name','label'=>'Employee'],['key'=>'period_start','label'=>'From'],['key'=>'period_end','label'=>'Through'],['key'=>'current_status','label'=>'Status'],['key'=>'overall_rating','label'=>'Rating']]" :actions="[['name'=>'details','label'=>'Open'],['name'=>'submit','label'=>'Submit','when'=>'can_edit'],['name'=>'delete','label'=>'Delete','danger'=>true,'when'=>'can_edit']]"/>
<x-hris.modal id="ipcr-modal" title="Create IPCR"><form id="ipcr-form" data-endpoint="/ipcr"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="period_start" type="date" required/><x-hris.field name="period_end" type="date" required/></div></div><div class="modal-footer"><button class="btn btn-primary">Create draft</button></div></form></x-hris.modal>
<x-hris.modal id="ipcr-work-modal" title="IPCR work plan"><div class="modal-body"><div id="ipcr-structure" class="mb-4"></div><div id="ipcr-draft-forms"><div class="row g-4"><form id="output-form" class="col-12 border rounded p-3"><h3 class="h6">1. Add output</h3><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="category" type="select" :options="[1=>'Strategic core function',2=>'Core function',3=>'Support function']" required/><x-hris.field name="task" class="col-12" type="textarea" required/></div><button class="btn btn-sm btn-primary mt-3">Add output</button></form><form id="indicator-form" class="col-12 border rounded p-3"><h3 class="h6">2. Add success indicator</h3><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="output_id" label="Output" type="select" required/><x-hris.field name="description" class="col-12" type="textarea" required/></div><button class="btn btn-sm btn-primary mt-3">Add indicator</button></form><form id="accomplishment-form" class="col-12 border rounded p-3"><h3 class="h6">3. Add accomplishment</h3><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="indicator_id" label="Success indicator" type="select" required/><x-hris.field name="accomplishment" class="col-12" type="textarea" required/></div><button class="btn btn-sm btn-primary mt-3">Add accomplishment</button></form></div></div><form id="rating-form" class="border rounded p-3 d-none"><h3 class="h6">Supervisor rating</h3><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="accomplishment_id" label="Accomplishment" type="select" required/>@foreach(['quality'=>'Quality','efficiency'=>'Efficiency','timeliness'=>'Timeliness'] as $name=>$label)<x-hris.field :name="$name" :label="$label" type="number" min="1" max="5"/>@endforeach</div><button class="btn btn-sm btn-primary mt-3">Save rating</button></form></div><div class="modal-footer"><a id="print-ipcr" class="btn btn-outline-secondary" target="_blank">Print</a></div></x-hris.modal>
@endsection
@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#ipcr-table'),outputForm=document.querySelector('#output-form'),indicatorForm=document.querySelector('#indicator-form'),accomplishmentForm=document.querySelector('#accomplishment-form'),ratingForm=document.querySelector('#rating-form');let current=null,detail=null;function selectOptions(select,items,label){select.replaceChildren(new Option('Choose…',''),...items.map(item=>new Option(label(item),item.id)))}function render(data){detail=data;const box=document.querySelector('#ipcr-structure');box.replaceChildren();data.outputs.forEach(output=>{const section=document.createElement('section');section.className='border rounded p-3 mb-2';const title=document.createElement('strong');title.textContent=`Category ${output.category}: ${output.task}`;section.append(title);output.indicators.forEach(indicator=>{const line=document.createElement('p');line.className='mb-1 mt-2';line.textContent=`Indicator: ${indicator.description}`;section.append(line);indicator.accomplishments.forEach(item=>{const small=document.createElement('div');small.className='small text-body-secondary';small.textContent=`Accomplishment: ${item.accomplishment} | Q ${item.quality??'-'} E ${item.efficiency??'-'} T ${item.timeliness??'-'}`;section.append(small)})});box.append(section)});const indicators=data.outputs.flatMap(x=>x.indicators),accomplishments=indicators.flatMap(x=>x.accomplishments);selectOptions(indicatorForm.elements.output_id,data.outputs,x=>x.task);selectOptions(accomplishmentForm.elements.indicator_id,indicators,x=>x.description);selectOptions(ratingForm.elements.accomplishment_id,accomplishments,x=>x.accomplishment)}async function refresh(){render(await HRIS.request(`/ipcr/${current.id}`));table.table.load()}async function open(row){current=row;render(await HRIS.request(`/ipcr/${row.id}`));outputForm.dataset.endpoint=`/ipcr/${row.id}/outputs`;document.querySelector('#ipcr-draft-forms').classList.toggle('d-none',!row.can_edit);ratingForm.classList.toggle('d-none',!row.can_rate);document.querySelector('#print-ipcr').href=`/ipcr/${row.id}/print`;HRIS.openModal('ipcr-work-modal')}indicatorForm.addEventListener('submit',()=>indicatorForm.dataset.endpoint=`/ipcr/${current.id}/outputs/${indicatorForm.elements.output_id.value}/indicators`);accomplishmentForm.addEventListener('submit',()=>accomplishmentForm.dataset.endpoint=`/ipcr/${current.id}/indicators/${accomplishmentForm.elements.indicator_id.value}/accomplishments`);ratingForm.addEventListener('submit',()=>ratingForm.dataset.endpoint=`/ipcr/${current.id}/accomplishments/${ratingForm.elements.accomplishment_id.value}/rate`);[outputForm,indicatorForm,accomplishmentForm,ratingForm].forEach(form=>HRIS.bindForm(form,{keepOpen:true,success:async()=>{form.reset();await refresh()}}));HRIS.bindForm(document.querySelector('#ipcr-form'),{success:(result)=>{table.table.load();setTimeout(()=>open({id:result.id,can_edit:true,can_rate:false}),250)}});table.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='details'){await open(row);return}if(await HRIS.confirm(`${action} this IPCR?`)){const url=action==='delete'?`/ipcr/${row.id}`:`/ipcr/${row.id}/submit`;HRIS.feedback((await HRIS.request(url,{method:action==='delete'?'DELETE':'POST'})).message);table.table.load()}}catch(e){HRIS.feedback(e.message,true)}})});</script>@endpush
